#!/usr/bin/env python3
from pathlib import Path
p=Path("public/index.html")
if not p.exists() or not Path("public/ux-dashboard-v2.js").exists():raise SystemExit("Run from repository root")
s=p.read_text()
if "/compact-mobile-page-actions.js" in s:raise SystemExit("Already installed. Do not run twice.")
if s.count("</head>")!=1 or s.count("</body>")!=1:raise SystemExit("Unexpected HTML structure")
s=s.replace("</head>",'<link rel="stylesheet" href="/compact-mobile-page-actions.css?v=1"></head>')
s=s.replace("</body>",'<script src="/compact-mobile-page-actions.js?v=1" defer></script></body>')
Path("public/compact-mobile-page-actions.js").write_text("(()=>{'use strict';\nconst pages={trips:'tripsPage',wishlist:'wishlistPage',shopping:'shoppingPage',towing:'towingPage',service:'servicePage',payload:'payloadPage',maintenance:'maintenancePage',checklists:'checklistsPage',profile:'checklistsPage'};\nconst mq=matchMedia('(max-width:900px)');\nfunction init(){\n const pin=document.getElementById('uxPinCurrent');\n if(!pin){setTimeout(init,300);return}\n const bar=pin.closest('.ux-page-pinbar');if(!bar)return;\n let source=null;\n const originalText=()=>pin.getAttribute('aria-pressed')==='true'?'Remove dashboard shortcut':'Add to dashboard';\n const setAppearance=()=>{\n  if(mq.matches&&bar.classList.contains('cmh-in-heading')){\n   if(pin.textContent!=='▦')pin.textContent='▦';\n   pin.title=originalText();\n   pin.setAttribute('aria-label',originalText());\n  }else{\n   pin.removeAttribute('title');\n   pin.removeAttribute('aria-label');\n   // Original controller updates button text on page navigation/click.\n   const label=pin.getAttribute('aria-pressed')==='true'?'✓ Added to my dashboard':'+ Add to my dashboard';\n   if(pin.textContent!==label)pin.textContent=label;\n  }\n };\n function restore(){\n  if(!source||!source.parentNode)return;\n  source.parentNode.insertBefore(bar,source);\n  source.remove();source=null;\n  bar.classList.remove('cmh-in-heading');\n }\n function sync(){\n  const key=document.body.dataset.currentPage||'trips';\n  const page=document.getElementById(pages[key]);\n  const heading=page?.querySelector(':scope > .toolbar, :scope > .section-head, :scope > .phase2 .section-head, :scope > .phase2 #serviceTab .section-head, :scope > .phase2 #payloadTab .section-head');\n  if(!mq.matches||!heading){restore();setAppearance();return}\n  if(bar.parentElement!==heading){\n   restore();\n   source=document.createElement('span');source.hidden=true;source.className='cmh-pin-placeholder';\n   bar.parentElement?.insertBefore(source,bar);\n   heading.append(bar);\n  }\n  heading.classList.add('cmh-compact-heading');\n  bar.classList.add('cmh-in-heading');\n  setAppearance();\n }\n // The existing dashboard controller repositions its button on navigation.\n window.addEventListener('planner:navigate',()=>{setTimeout(sync,70);setTimeout(sync,450)});\n window.addEventListener('hashchange',()=>setTimeout(sync,100));\n mq.addEventListener('change',sync);\n pin.addEventListener('click',()=>setTimeout(setAppearance,120));\n // Detect delayed controller reparenting and reapply compact positioning.\n const observer=new MutationObserver(()=>{clearTimeout(init._syncTimer);init._syncTimer=setTimeout(sync,80)});\n observer.observe(document.querySelector('main')||document.body,{childList:true,subtree:true});\n setTimeout(sync,500);\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();\n})();")
Path("public/compact-mobile-page-actions.css").write_text('/* Compact primary page action + dashboard shortcut in one header row */\n@media(max-width:900px){\n #tripsPage>.toolbar,\n #wishlistPage>.toolbar,\n #shoppingPage>.toolbar,\n #towingPage>.toolbar,\n #servicePage .section-head.cmh-compact-heading,\n #payloadPage .section-head.cmh-compact-heading{\n  display:flex!important;flex-direction:row!important;flex-wrap:wrap!important;\n  align-items:center!important;gap:8px!important;\n  margin-top:8px!important;margin-bottom:10px!important;\n }\n .cmh-compact-heading>h2,\n .cmh-compact-heading>div:first-child{flex:1 1 140px!important;min-width:0!important;margin:0!important}\n .cmh-compact-heading>div:first-child h2{margin:0!important}\n .cmh-compact-heading>div:first-child p{display:none!important}\n .cmh-compact-heading>.actions{display:flex!important;align-items:center!important;margin:0!important;flex:0 0 auto!important;gap:6px!important}\n .cmh-compact-heading>.actions button,\n .cmh-compact-heading>button:not(.ux-page-pinbar button){\n  width:auto!important;min-width:0!important;min-height:40px!important;\n  padding:9px 12px!important;font-size:13px!important;line-height:1.1!important;\n  white-space:nowrap!important;margin:0!important\n }\n .cmh-compact-heading>.ux-page-pinbar{\n  display:flex!important;align-items:center!important;justify-content:center!important;\n  flex:0 0 auto!important;margin:0!important;padding:0!important;\n  order:3!important;width:auto!important\n }\n .cmh-compact-heading>.ux-page-pinbar button{\n  display:flex!important;align-items:center!important;justify-content:center!important;\n  width:42px!important;height:42px!important;min-width:42px!important;min-height:42px!important;\n  padding:0!important;margin:0!important;font-size:23px!important;line-height:1!important;\n  border-radius:11px!important\n }\n #tripsPage>.toolbar h2{font-size:clamp(19px,5vw,25px)!important;line-height:1.2!important}\n #tripsPage>.toolbar{padding:0!important}\n #tripsPage>.filters-disclosure{margin-top:0!important}\n}\n@media(min-width:901px){.cmh-pin-placeholder{display:none!important}}')
p.write_text(s)
print("Compact page heading actions installed. No database migration.")
